from math import sqrt
from sympy import factorint

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def prime_factors(n):
    factors = factorint(n)
    return factors

def check_pair(a, b):
    factors_a = prime_factors(a)
    factors_b = prime_factors(b)
    for p in factors_a:
        if factors_a[p] < 2:
            return False
    for p in factors_b:
        if factors_b[p] < 2:
            return False
    return True

def find_pairs(n):
    pairs = []
    for i in range(2, n):
        a = i
        b = i + 1
        if check_pair(a, b):
            pairs.append([a, b])
    return pairs

pairs = find_pairs(1000)
print(pairs)
```

