import math

def is_prime_factors_not_less_than_2(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            count = 0
            while n % i == 0:
                n //= i
                count += 1
            if count < 2:
                return False
    if n > 1:
        return False
    return True

pairs = []
n = 8
while len(pairs) < 7:
    if is_prime_factors_not_less_than_2(n) and is_prime_factors_not_less_than_2(n + 1):
        pairs.append(n)
    n += 1
print(pairs)
```

